INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('yercaud', 1, 4, 'go',
  'Peak Yercaud window. 12-26C at 1500m. Lake, Pagoda Point, Lady''s Seat clear. Coffee estates dry.',
  'January is the cleanest weather window at Yercaud. Daytime 22-26C, nights 12-15C. Yercaud Lake, Pagoda Point, Lady''s Seat viewpoint all at full operations. Anna Park (₹15, 8am-6pm) at light visitor load. Coffee estate walks at year-driest.',
  NULL,
  'Yercaud in January is the version that earned the hill station its nickname "Poor Man''s Ooty." Sitting at 1500m on the Shervaroy Hills — the Eastern Ghats counterpart to the Nilgiris, only 32km from Salem and 220km from Bangalore — Yercaud is 60-70 percent cheaper than Ooty across the board with a fraction of the crowds. Daytime 22-26C, nights 12-15C, rainfall under 25mm. Yercaud Lake (1km from town centre, the artificial reservoir constructed by the British in the 1820s) at full boat-house tempo — pedal boats ₹150/30min, motorboats ₹250. Pagoda Point (3km, free, 6am-6pm), Lady''s Seat (4km, the cliff-edge viewpoint overlooking Salem plains 1300m below, ₹15 entry, 7am-6pm) at year-clearest sightlines. Anna Park (Botanical Garden, 2km, ₹15, 8am-6pm), Bear Cave (5km), Killiyur Falls (3km, dry-season trickle), Shervaroyan Temple (5km, the Shevaroyan hill summit at 1620m), Servarayan Hill viewpoint round the day-trip set. Coffee estates around Yercaud (the original Robusta coffee terroir of Tamil Nadu, distinct from Karnataka''s Coorg) at year-driest — Yercaud Coffee plantation walks ₹200-400.'
)
