INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('yercaud', 2, 5, 'go',
  'Driest month. 13-27C. Sightlines cleanest. Coffee estates at year-best. Rates 15 percent below January.',
  'February is the technical sweet spot — rainfall under 15mm, Lady''s Seat sightline cleanest, Pagoda Point clear past 50km. Coffee estate walks at year-best clarity. Rates 15 percent below January.',
  NULL,
  'Yercaud in February is the cleanest weather month at the Eastern Ghats hill station. Rainfall averages 10-15mm, daytime 22-27C, nights 13-16C. Lady''s Seat (4km, ₹15, 7am-6pm) at year-clearest sightlines — the Salem plains visible to the south, the entire Mettur dam reservoir visible to the southwest, sightlines past 100km on clearest mornings. Pagoda Point (3km, free) at full visibility — the Shervaroy summit visible to the north. Yercaud Lake (1km, the 1820s British-era artificial reservoir) at light visitor load — pedal boats ₹150/30min, motorboats ₹250. Anna Park (Botanical Garden, 2km, ₹15, 8am-6pm) at quietest perennial-border tempo. Bear Cave (5km), Killiyur Falls (3km, dry-season trickle), Shervaroyan Temple (5km, the Shevaroyan hill summit at 1620m — Tamil Nadu''s highest in Eastern Ghats), Servarayan Hill viewpoint workable. Coffee estate walks at year-best clarity: Yercaud Coffee plantation walks ₹200-400 cover Robusta and Arabica plots, the curing-and-processing demonstration, the small Indian Cardamom co-plantings. The Tirupathur-Mettur viewline from Karadiyur viewpoint at year-clearest.'
)
