INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('yercaud', 3, 5, 'go',
  'Cool-dry holds. 14-28C. Coffee flowering visible. Last quiet month before April Summer Festival.',
  'March extends February''s pattern with bonus of Robusta coffee flowering at established estates. Last quiet month before April Summer Festival (Apr 22-30) drives heavy visitor concentration. Rates 20 percent below January.',
  NULL,
  'Yercaud in March is the soft-landing month with the bonus of Robusta coffee flowering at established estates. Daytime 23-28C, nights 14-17C, humidity climbing toward 65 percent in the last fortnight, rainfall under 25mm. Coffee flowering visible at the established Yercaud Coffee plantations (Robusta variety) — the 3-4 week pre-monsoon flush, white star-shaped blossoms across the Servarayan slopes, plantation walks ₹200-400 at year-best photographic interest. Lady''s Seat (4km, ₹15, 7am-6pm) at year-clearest sightlines — the Salem plains and Mettur dam reservoir visible to the south. Pagoda Point (3km, free) at full visibility. Yercaud Lake (1km, the 1820s reservoir) at light load. Anna Park (₹15, 8am-6pm), Bear Cave (5km), Killiyur Falls (3km, year-low flow), Shervaroyan Temple (5km, at the Shevaroyan summit 1620m) workable. Karadiyur viewpoint at year-clearest. Holi long weekend brings a 3-day domestic bump from Salem, Tirupathur, Krishnagiri families. Hotel rates ease 5 percent versus February: heritage (Grange Resort, Sterling Yercaud) at ₹3,800-6,500, mid-bracket ₹2,300-3,800, homestays ₹1,100-1,800. Quieter than Ooty/Kodai by 6-8x even on weekends.'
)
