INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('yercaud', 4, 5, 'go',
  'Summer Festival peak. 16-30C. Apr 22-30 festival week. Rates 1.8-2.2x. Book 3-4 weeks ahead.',
  'April is when Yercaud hosts its annual Summer Festival (typically Apr 22-30, organised by TN Tourism). Flower show, dog show, dance and music performances at the Anna Park. Rates 1.8-2.2x normal during festival week. Coffee flowering peaks.',
  NULL,
  'Yercaud in April runs at its loudest week — the annual Summer Festival typically Apr 22-30, organised by the Tamil Nadu Tourism Development Corporation since 1981. Daytime 23-30C, nights 16-19C, humidity 65-70 percent, pre-monsoon rainfall 50-80mm in the last 10 days. The Yercaud Summer Festival anchors at Anna Park (2km from town, the Botanical Garden) — flower show with 200+ varieties on display, dog show, traditional dance and music performances, boat races on Yercaud Lake, fruit show with Eastern Ghats produce. The festival concentrates 40,000-60,000 visitors over the 9 days. Robusta coffee flowering peaks at established estates — Yercaud Coffee plantation walks ₹200-400 at year-best floral display, the white star-blooms across the Servarayan slopes. Lady''s Seat (4km, ₹15), Pagoda Point (3km, free), Yercaud Lake boat house all at festival-week peak crowd. Bear Cave (5km), Killiyur Falls (3km, year-low flow), Shervaroyan Temple (5km) operational. Hotel rates 1.8-2.2x normal during festival week: heritage (Grange Resort, Sterling Yercaud) at ₹8-13k, mid-bracket ₹5-7k, homestays ₹2,500-3,500. Pre-festival fortnight (Apr 1-21) holds normal off-season rates.'
)
