INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('yercaud', 5, 4, 'go',
  'Summer-migration spillover. 18-30C. First fortnight clean, last 10 days bring SW-monsoon advance.',
  'Early May extends April — coffee flowering peak, sightlines clear, hotel rates at off-festival levels. Last 10 days bring SW-monsoon advance squalls. Yercaud catches lighter SW rain than Western Ghats but enough to compromise late-May plans.',
  NULL,
  'Yercaud in May splits cleanly in two. The first fortnight extends April: daytime 23-30C, nights 18-21C, humidity 70 percent. Robusta coffee flowering peak still visible at Yercaud Coffee plantations — the white star-bloom flush across Servarayan slopes. Lady''s Seat (4km, ₹15), Pagoda Point (3km, free), Yercaud Lake (1km), Anna Park (2km, ₹15) at full operations. Summer-migration spillover from the Tamil Nadu plains (Salem, Tirupathur, Erode, Krishnagiri) keeps weekday weekend traffic 2-3x March levels. By the third week, SW monsoon advance squalls hit the Eastern Ghats Shervaroy face — Yercaud at 1500m catches lighter SW monsoon than the Western Ghats Anamalai/Nilgiris (annual 1,500-2,000mm versus Valparai 2,500-4,000mm) but the last fortnight gets the first taste. Lady''s Seat and Pagoda Point sightlines collapse on rainy afternoons; the Salem plains visibility from the south face cuts to under 30km. Killiyur Falls (3km) begins building. Hotel rates stay at off-season levels through the back half: heritage at ₹3,500-6,000, mid-bracket ₹2,200-3,500, homestays ₹1,100-1,800.'
)
