INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('yercaud', 6, 3, 'wait',
  'SW monsoon onset. 16-25C, 100-200mm rainfall. Lighter than Western Ghats. Lady''s Seat and Pagoda Point fogged afternoons.',
  'June brings the SW monsoon to the Eastern Ghats face — lighter than Western Ghats but enough to fog sightlines on afternoons. Coffee estate walks suspend through the heaviest weeks. October-November is the cleaner call.',
  'June brings lighter monsoon to Yercaud than the Western Ghats (Ooty, Coonoor, Valparai) — 100-200mm versus those hill stations'' 200-1000mm — but Lady''s Seat and Pagoda Point sightlines still fog out on most afternoons. Coffee estate walks suspend through the heaviest rain weeks. October is the cleaner call.',
  'Yercaud in June is when the SW monsoon arrives at the Eastern Ghats Shervaroy face. Rainfall 100-200mm across 12-16 wet days at the 1500m elevation; Yercaud catches lighter SW monsoon than the Western Ghats hill stations (Ooty/Coonoor/Valparai) since the Eastern Ghats sit in the partial rain-shadow of the Western Ghats. Daytime 19-25C, nights 16-19C, humidity 85 percent. Lady''s Seat (4km, ₹15, 7am-6pm) loses sightlines past 50m on rainy afternoons but morning visibility holds 3-4 days per week. Pagoda Point (3km, free), Yercaud Lake (1km) workable on clear mornings. Anna Park (2km, ₹15, 8am-6pm) and Bear Cave (5km) stay open at 60 percent visitor drop. Coffee estate walks at Yercaud Coffee suspend through the heaviest rain weeks — the coffee plants need rain but the walks are cancelled. Killiyur Falls (3km) builds rapidly. NH79 Salem-Yercaud 22-hairpin climb stays mostly open; closures rare (the Eastern Ghats face less landslide-prone than the Western Ghats), afternoon rain delays of 30-90 minutes typical. Hotel rates drop 40 percent from January: heritage at ₹3-5k, mid-bracket ₹2-3.5k, homestays ₹900-1,500. October is the cleaner call.'
)
