INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('yercaud', 7, 2, 'wait',
  'Peak SW monsoon, lighter than Western Ghats. 16-24C, 150-300mm rainfall. Sightlines erratic. Wait for October.',
  'July is the wettest stretch at Yercaud but materially lighter than Western Ghats (150-300mm vs Valparai 700-1000mm). Lady''s Seat and Pagoda Point sightlines erratic. Coffee walks suspended. Wait for October.',
  'July is the wettest stretch at Yercaud (150-300mm) but materially lighter than Western Ghats hill stations (Valparai 700-1000mm, Ooty 800-1200mm). Lady''s Seat and Pagoda Point sightlines erratic — workable some mornings, fogged most afternoons. Coffee estate walks suspended. October is the cleaner call.',
  'Yercaud in July is the year''s wettest stretch at the Eastern Ghats hill station — but lighter than the Western Ghats face by a factor of 3-5x. Rainfall 150-300mm across 16-20 wet days at the 1500m elevation. Daytime 19-24C, nights 16-19C, humidity 90 percent. Lady''s Seat (4km, ₹15, 7am-6pm) workable on dry-morning windows 3-4 days per week; sightlines absent on rainy afternoons. Pagoda Point (3km, free) similar pattern. Yercaud Lake (1km) at full reservoir but boat operations suspend on heavy-water days. Anna Park (2km, ₹15) and Bear Cave (5km) stay open at 75 percent visitor drop. Coffee estate walks at Yercaud Coffee suspended through the month — the plucking weeks at lower elevations conflict with rain access. Killiyur Falls (3km) and Shervaroy temple cascade at building post-monsoon flow. NH79 Salem-Yercaud 22-hairpin climb mostly open; rare closures (Eastern Ghats less landslide-prone than Western Ghats). Hotel rates at year-low: heritage at ₹2,500-4,500, mid-bracket ₹1,800-3,000, homestays ₹800-1,400. Wait for October for the cleaner Yercaud window.'
)
