INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('yercaud', 8, 2, 'wait',
  'SW monsoon continues. 16-24C, 100-200mm rainfall. Sightlines erratic, coffee walks suspended. Wait for October.',
  'August holds the July pattern with marginally fewer extreme-rain days — 100-200mm rainfall, sightlines erratic, coffee walks suspended. Wait for October-November return to operations.',
  'August holds the July pattern at Yercaud with marginally fewer extreme-rain days — 100-200mm rainfall, Lady''s Seat and Pagoda Point sightlines erratic, Yercaud Coffee estate walks suspended through the heaviest plucking weeks. October-November is the cleaner call.',
  'Yercaud in August holds the July monsoon pattern with marginally fewer extreme-rain days. Rainfall 100-200mm across 14-18 wet days. Daytime 19-24C, nights 16-19C, humidity 90 percent. Lady''s Seat (4km, ₹15) workable on dry-morning windows 4-5 days per week; afternoons fog out. Pagoda Point (3km, free) similar — the Salem plains sightline absent through most rain weeks. Yercaud Lake (1km) at full reservoir, boat operations sporadic. Anna Park (2km, ₹15, 8am-6pm) at light visitor load. Bear Cave (5km) and Killiyur Falls (3km) workable on dry days. Coffee estate walks at Yercaud Coffee suspended through the heaviest plucking weeks. NH79 Salem-Yercaud 22-hairpin climb stays open; rain delays 30-60 minutes on heavy afternoons. Independence Day (Aug 15) brings a 3-day weekend bump from Salem, Erode, Krishnagiri families seeking cool relief from plains heat — most leave underwhelmed by rain-impacted sightlines. Hotel rates at year-low through early August, climbing 15 percent for Aug 15 weekend: heritage at ₹2,500-4,500, mid-bracket ₹1,800-3,000, homestays ₹800-1,400. October is the cleaner call.'
)
