INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('yercaud', 9, 4, 'go',
  'SW monsoon retreats. 15-25C, 80-150mm rainfall. Coffee walks resume. Sightlines clear afternoons.',
  'September is the proper season opener. SW monsoon retreats by week three, Lady''s Seat sightlines clear on afternoons. Coffee estate walks resume. Killiyur Falls at year-peak post-monsoon flow. Hotel rates 25 percent below December.',
  NULL,
  'Yercaud in September is the soft re-opening with the bonus of Killiyur Falls at peak post-monsoon flow. Rainfall drops to 80-150mm across 10-13 wet days, mostly the first fortnight as the SW monsoon retreats from the Shervaroy face. Daytime 21-25C, nights 15-18C, humidity easing toward 75 percent. Lady''s Seat (4km, ₹15, 7am-6pm) afternoon sightlines return — the Salem plains and Mettur dam reservoir visible to the south on clearing afternoons. Pagoda Point (3km, free) at full visibility. Yercaud Lake (1km) at full operations — pedal boats ₹150/30min, motorboats ₹250. Anna Park (2km, ₹15) at light perennial-border tempo. Killiyur Falls (3km) hits year-peak flow — 5-7x dry-season volume. Bear Cave (5km), Shervaroyan Temple (5km, the Shevaroyan summit at 1620m — TN''s highest Eastern Ghats peak), Karadiyur viewpoint workable. Coffee estate walks at Yercaud Coffee resume from Sep 15-20 — the post-monsoon Robusta picking starts in mid-September, plantation walks ₹200-400 with bean-picking demonstration. NH79 Salem-Yercaud 22-hairpin climb stabilises with closure events rare.'
)
