INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('yercaud', 10, 5, 'go',
  'Full operations resume. 14-25C, 100-180mm rainfall residual. Coffee picking peak. Killiyur still strong.',
  'October is the proper hill-station window. All viewpoints back at high visibility, coffee picking at peak, Killiyur Falls still strong. NE monsoon residual brings evening showers but daytime mostly clear. Rates 20 percent below December.',
  NULL,
  'Yercaud in October is when the Eastern Ghats hill station hits full operations with Robusta coffee picking at peak. Daytime 21-25C, nights 14-17C, rainfall 100-180mm split across the SW retreat (first 10 days) and NE monsoon arrival (last 10 days), humidity dropping toward 70 percent. Lady''s Seat (4km, ₹15, 7am-6pm) at full afternoon sightlines — the Salem plains visible to the south past 80km. Pagoda Point (3km, free) at full visibility. Yercaud Lake (1km, the 1820s reservoir) at full boat-house operations. Anna Park (2km, ₹15) at light visitor load. Killiyur Falls (3km) still carries 4-5x dry-season volume from September peak. Bear Cave (5km), Shervaroyan Temple (5km, at 1620m), Karadiyur viewpoint at full operations. Coffee picking at year-peak — Robusta variety plucked through October-November, the plantation walks at Yercaud Coffee (₹200-400) cover picking, curing, processing demonstrations. NE monsoon brings 1-2 hour evening downpours typical 4-7pm but daytime mostly clear. Hotel rates climb 15 percent from September: heritage at ₹3,600-6,000, mid-bracket ₹2,300-3,800, homestays ₹1,300-2,000.'
)
