INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('yercaud', 11, 5, 'go',
  'Cold-dry. 12-24C. Sightlines cleanest. Coffee picking continues. Rates climb 15 percent through month.',
  'November is the genuine pivot to Yercaud high season. NE monsoon residual spent by mid-month, rainfall under 50mm, Lady''s Seat sightlines at year-clearest. Hotel rates climb 15 percent as Christmas-week traffic begins booking.',
  NULL,
  'Yercaud in November is when the Eastern Ghats hill station turns the corner. Northeast monsoon residual eases to under 50mm across 4-6 wet days, all in the first 10 days. Daytime 21-24C, nights 12-15C, humidity dropping under 70 percent. Lady''s Seat (4km, ₹15, 7am-6pm) at year-clearest sightlines — the Salem plains, the Mettur dam reservoir, the Tirupathur valley all visible past 100km. Pagoda Point (3km, free) at peak photogenicity — the Shervaroy summit visible to the north at 1620m elevation. Yercaud Lake (1km, the 1820s artificial reservoir) at full boat-house tempo with light visitor load. Anna Park (2km, ₹15, 8am-6pm) at second-flush perennial-border bloom; the local Horticulture Department chrysanthemum display typically the last week of November. Killiyur Falls (3km) still carries 2-3x dry-season volume. Bear Cave (5km), Shervaroyan Temple (5km, the Shevaroyan summit at 1620m), Karadiyur viewpoint at full operations. Coffee picking at Yercaud Coffee plantations continues — Robusta peak November plucking, the plantation walks (₹200-400) at year-busiest visitor tempo.'
)
