INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('yercaud', 12, 5, 'go',
  'Peak season. 10-25C. Christmas-NY rates 1.6-1.9x. Still quieter and cheaper than Ooty/Kodai. Book 2-3 weeks ahead.',
  'December is Yercaud''s most reliable window — peak Eastern Ghats weather, full operations. Christmas-NY week drives rates to 1.6-1.9x base. Yercaud stays 50-60 percent cheaper than Ooty/Kodai through the rate-peak weeks.',
  NULL,
  'Yercaud in December is the year''s most coherent window with the bonus of staying the cheapest of the four major South Indian hill stations. Daytime 22-25C, nights 10-13C, rainfall under 30mm, humidity 65 percent. Christmas-NY week (December 22 to January 5) is the tight stretch but materially milder than Ooty/Kodai/Coonoor: heritage (Grange Resort, Sterling Yercaud) climbs to ₹7,500-12,000 against ₹4-7k off-peak; mid-bracket hits ₹4,500-7,000 against ₹2,500-4k off-peak; homestays double to ₹2,500-3,500. Lady''s Seat (4km, ₹15, 7am-6pm) at year-clearest sightlines — the Salem plains, Mettur dam reservoir, Tirupathur valley visible past 100km. Pagoda Point (3km, free), Yercaud Lake (1km, the 1820s reservoir), Anna Park (2km, ₹15), Bear Cave (5km), Shervaroyan Temple (5km, at 1620m), Killiyur Falls (3km), Karadiyur viewpoint all at full operations with peak monthly footfall. The 32km Salem-Yercaud 22-hairpin NH79 climb queues 30-45 minutes through Christmas-NY weekend afternoons. Yercaud Coffee plantation walks (₹200-400) at year-busiest. Coffee picking continues — Robusta tail of season.'
)
